
function vxEventTypeOptions161003(selected){
  var groups=[
    ['BOOKING / CASTING',['Casting','Go & See','Fitting','Editorial','Campaign','Runway']],
    ['DEVELOPMENT',['Evaluation','Training','Test','Digitals']],
    ['OPERATIONS',['Travel','Meeting','Task']],
    ['OPTIONS',['Option 1','Option 2','Option 3']]
  ];
  return groups.map(function(g){
    return '<optgroup label="'+g[0]+'">'+g[1].map(function(v){
      return '<option value="'+v+'"'+(String(selected||'')===v?' selected':'')+'>'+v+'</option>';
    }).join('')+'</optgroup>';
  }).join('');
}

